export type OnboardingStep = {
  id: string;
  targetSelector?: string;
  title: string;
  description: string;
  placement: "top" | "bottom" | "left" | "right" | "center";
  advanceOn?: {
    /** DOM event to listen for on the target element (e.g., "click") */
    event?: string;
    /** Element to listen on (defaults to targetSelector) */
    selector?: string;
    /** Advance when this selector appears in the DOM (polling) */
    waitForSelector?: string;
  };
  /** If true, the step can only be advanced via the Next button (no auto-advance). */
  manualAdvance?: boolean;
  onBeforeStep?: () => void;
};

export const TOUR_STEPS: OnboardingStep[] = [
  {
    id: "telescope-icon",
    targetSelector:
      '.side-dock-ribbon-action[aria-label="Toggle discourse context"]',
    title: "Discourse Context Panel",
    description:
      "Click the telescope icon to open the Discourse Context sidebar.",
    placement: "right",
    advanceOn: { event: "click" },
  },
  {
    id: "open-command-palette",
    title: "Open the Command Palette",
    description:
      "Press Cmd+P (Mac) or Ctrl+P (Windows/Linux) to open the command palette.",
    placement: "center",
    advanceOn: { waitForSelector: ".prompt" },
  },
  {
    id: "create-discourse-node",
    targetSelector: ".prompt",
    title: "Create a Discourse Node",
    description:
      'Type "Create discourse node" in the search bar and select it from the list.',
    placement: "bottom",
    manualAdvance: true,
  },
];
import { createRoot, Root } from "react-dom/client";
import React from "react";
import { OnboardingTour } from "./OnboardingTour";
import { PluginProvider } from "~/components/PluginContext";
import type DiscourseGraphPlugin from "~/index";

export class OnboardingTourManager {
  private root: Root | null = null;
  private container: HTMLDivElement | null = null;
  private plugin: DiscourseGraphPlugin;

  constructor(plugin: DiscourseGraphPlugin) {
    this.plugin = plugin;
  }

  start() {
    if (this.root) return; // Prevent double-start

    this.container = document.createElement("div");
    this.container.id = "discourse-graph-onboarding-tour";
    document.body.appendChild(this.container);

    this.root = createRoot(this.container);
    this.root.render(
      React.createElement(
        PluginProvider,
        { plugin: this.plugin },
        React.createElement(OnboardingTour, {
          onComplete: () => this.stop(),
        }),
      ),
    );
  }

  stop() {
    if (this.root) {
      this.root.unmount();
      this.root = null;
    }
    if (this.container) {
      this.container.remove();
      this.container = null;
    }
  }
}
import { useState, useEffect, useCallback, useRef } from "react";
import { TOUR_STEPS } from "./onboardingSteps";
import type { OnboardingStep } from "./onboardingSteps";

export type TargetRect = {
  top: number;
  left: number;
  width: number;
  height: number;
};

export const useOnboardingTour = (onComplete: () => void) => {
  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [isActive, setIsActive] = useState(true);
  const [targetRect, setTargetRect] = useState<TargetRect | null>(null);
  const [targetNotFound, setTargetNotFound] = useState(false);
  const rafRef = useRef<number | null>(null);

  const currentStep: OnboardingStep | undefined = TOUR_STEPS[currentStepIndex];
  const hasTarget = !!currentStep?.targetSelector;

  const dismiss = useCallback(() => {
    setIsActive(false);
    onComplete();
  }, [onComplete]);

  const next = useCallback(() => {
    if (currentStepIndex + 1 >= TOUR_STEPS.length) {
      dismiss();
    } else {
      setCurrentStepIndex((i) => i + 1);
      setTargetNotFound(false);
      setTargetRect(null);
    }
  }, [currentStepIndex, dismiss]);

  // Track target element position (only for steps with a targetSelector)
  useEffect(() => {
    if (!isActive || !currentStep?.targetSelector) return;

    currentStep.onBeforeStep?.();

    const updateRect = () => {
      const el = document.querySelector(currentStep.targetSelector!);
      if (el) {
        const rect = el.getBoundingClientRect();
        setTargetRect({
          top: rect.top,
          left: rect.left,
          width: rect.width,
          height: rect.height,
        });
        setTargetNotFound(false);
      } else {
        setTargetRect(null);
        setTargetNotFound(true);
      }
      rafRef.current = requestAnimationFrame(updateRect);
    };

    rafRef.current = requestAnimationFrame(updateRect);

    return () => {
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, [isActive, currentStep]);

  // Run onBeforeStep for no-target steps
  useEffect(() => {
    if (!isActive || !currentStep || currentStep.targetSelector) return;
    currentStep.onBeforeStep?.();
  }, [isActive, currentStep]);

  // Listen for advanceOn event-based action
  useEffect(() => {
    if (!isActive || !currentStep?.advanceOn?.event) return;

    const advanceOn = currentStep.advanceOn;
    const targetSelector = advanceOn.selector || currentStep.targetSelector;
    if (!targetSelector) return;

    const el = document.querySelector(targetSelector);
    if (!el) return;

    const handler = () => {
      next();
    };

    el.addEventListener(advanceOn.event!, handler, { once: true });

    return () => {
      el.removeEventListener(advanceOn.event!, handler);
    };
  }, [isActive, currentStep, next]);

  // Listen for advanceOn waitForSelector (poll for element appearance)
  useEffect(() => {
    if (!isActive || !currentStep?.advanceOn?.waitForSelector) return;

    const selector = currentStep.advanceOn.waitForSelector;
    let animFrameId: number;

    const poll = () => {
      if (document.querySelector(selector)) {
        next();
        return;
      }
      animFrameId = requestAnimationFrame(poll);
    };

    animFrameId = requestAnimationFrame(poll);

    return () => {
      cancelAnimationFrame(animFrameId);
    };
  }, [isActive, currentStep, next]);

  return {
    isActive,
    currentStep,
    currentStepIndex,
    totalSteps: TOUR_STEPS.length,
    targetRect,
    targetNotFound,
    hasTarget,
    next,
    dismiss,
  };
};
import type { DriveStep } from "driver.js";

/**
 * Phase 1: Highlight the telescope ribbon icon.
 * User clicks the icon or the Next button to advance.
 */
export const telescopeStep: DriveStep = {
  element: '.side-dock-ribbon-action[aria-label="Toggle discourse context"]',
  popover: {
    title: "Discourse Context Panel",
    description:
      "Click the telescope icon to open the Discourse Context sidebar.",
    side: "right",
    align: "start",
  },
};

/**
 * Phase 2: No target element — displayed as a vanilla floating card.
 * driver.js cannot highlight "nothing", so we skip it entirely for this phase.
 */
export const commandPalettePromptStep = {
  title: "Open the Command Palette",
  description:
    "Press Cmd+P (Mac) or Ctrl+P (Windows/Linux) to open the command palette.",
} as const;

/**
 * Phase 3: Highlight the command palette input (.prompt).
 * Shown after the palette opens. Finish button ends the tour.
 */
export const commandPaletteHighlightStep: DriveStep = {
  element: ".prompt",
  popover: {
    title: "Create a Discourse Node",
    description:
      'Type "Create discourse node" in the search bar and select it from the list.',
    side: "bottom",
    align: "start",
  },
};
